import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"@jsprismarine/console","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"@jsprismarine/console"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/console/"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/console/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/console/src"}},"headers":[],"relativePath":"api/@jsprismarine/console/index.md","filePath":"api/@jsprismarine/console/index.md","lastUpdated":1794050835000}`),a={name:`api/@jsprismarine/console/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<p><a href="./../../">JSPrismarine</a> / @jsprismarine/console</p><h1 id="jsprismarine-console" tabindex="-1">@jsprismarine/console <a class="header-anchor" href="#jsprismarine-console" aria-label="Permalink to “@jsprismarine/console”">​</a></h1><p><a href="https://discord.gg/kZZCDyCBbW" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/console" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/console" alt="npm"></a></p><p>Terminal user interface for the JSPrismarine server console, built on <a href="https://opentui.com" target="_blank" rel="noreferrer">OpenTUI</a>.</p><p>The server entry point in <code>@jsprismarine/server</code> imports this package lazily, and only when it has decided to run the UI: stdin and stdout are a terminal, <code>JSP_NO_TUI</code> and <code>--no-tui</code> are absent, and Node can load <code>node:ffi</code> (26.9 or newer, or 26.4 with <code>--experimental-ffi</code>). In every other situation the server uses its plain line console and this package is never loaded, so a Docker image or a hosting panel pays nothing for it. The UI talks to the server over the messages in <code>@jsprismarine/console-protocol</code>; nothing outside this package imports <code>@opentui/core</code>.</p><p>Requires Node.js 26.9 or later, or 26.4 and later started with <code>--experimental-ffi</code>: OpenTUI calls its native renderer through <code>node:ffi</code>, which shipped in 26.4 behind a flag and is on by default from 26.9. Older versions can&#39;t load the renderer, which is why the server falls back to the plain console instead of failing.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><p>Each component is a factory in its own file, <code>create&lt;Name&gt;(ctx, props)</code>, with a sibling <code>*.test.ts</code>. Logic that doesn&#39;t need a renderer (log windowing, history, completion, segment truncation) lives in plain modules with their own tests.</p><table tabindex="0"><thead><tr><th>Directory</th><th>Owns</th></tr></thead><tbody><tr><td><code>src/theme/</code></td><td>Color roles resolved against the terminal&#39;s capabilities, and styled text with Minecraft <code>§</code> codes</td></tr><tr><td><code>src/log/</code></td><td>Bounded log storage with filter-aware retention, windowed rendering, line formatting, and badges</td></tr><tr><td><code>src/input/</code></td><td>The input bar, command history, and completion state</td></tr><tr><td><code>src/status/</code></td><td>The status bar, its segments, and toasts</td></tr><tr><td><code>src/help/</code></td><td>The help overlay generated from the key map</td></tr><tr><td><code>src/tps/</code></td><td>TPS history, the braille line chart shared by the details pane, and the TPS page</td></tr><tr><td><code>src/app/</code></td><td>Layout, breakpoints, focus, and wiring; exports <code>startConsole</code></td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to “Tests”">​</a></h2><p>From the repository root, <code>pnpm exec vitest run packages/console</code> runs this package&#39;s tests. They render into OpenTUI&#39;s test renderer, so they need a Node that loads <code>node:ffi</code> too.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="consolehandle" tabindex="-1">ConsoleHandle <a class="header-anchor" href="#consolehandle" aria-label="Permalink to “ConsoleHandle”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L58" target="_blank" rel="noreferrer">startConsole.ts:58</a></p><p>A running console.</p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h4><h5 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h5><blockquote><p><strong>close</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L60" target="_blank" rel="noreferrer">startConsole.ts:60</a></p><p>Saves history, destroys the renderer, waits for the terminal to be restored, and removes the fallback handlers.</p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="startconsoleoptions" tabindex="-1">StartConsoleOptions <a class="header-anchor" href="#startconsoleoptions" aria-label="Permalink to “StartConsoleOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L39" target="_blank" rel="noreferrer">startConsole.ts:39</a></p><p>Everything <a href="#startconsole">startConsole</a> needs from the host.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="createrenderer" tabindex="-1">createRenderer? <a class="header-anchor" href="#createrenderer" aria-label="Permalink to “createRenderer?”">​</a></h5><blockquote><p><code>optional</code> <strong>createRenderer?</strong>: (<code>config</code>) =&gt; <code>Promise</code>&lt;<code>CliRenderer</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L54" target="_blank" rel="noreferrer">startConsole.ts:54</a></p><p>Builds the renderer. Tests inject <code>createTestRenderer</code>; production uses <code>createCliRenderer</code>.</p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="config" tabindex="-1">config <a class="header-anchor" href="#config" aria-label="Permalink to “config”">​</a></h6><p><code>CliRendererConfig</code></p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>Promise</code>&lt;<code>CliRenderer</code>&gt;</p><h5 id="env" tabindex="-1">env? <a class="header-anchor" href="#env" aria-label="Permalink to “env?”">​</a></h5><blockquote><p><code>optional</code> <strong>env?</strong>: <code>ProcessEnv</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L48" target="_blank" rel="noreferrer">startConsole.ts:48</a></p><p>Environment read for <code>NO_COLOR</code>, <code>JSP_DIR</code>, <code>VISUAL</code>, and <code>EDITOR</code>; defaults to <code>process.env</code>.</p><h5 id="historyfile" tabindex="-1">historyFile? <a class="header-anchor" href="#historyfile" aria-label="Permalink to “historyFile?”">​</a></h5><blockquote><p><code>optional</code> <strong>historyFile?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L42" target="_blank" rel="noreferrer">startConsole.ts:42</a></p><p>Where command history is read and written. Defaults to <code>${JSP_DIR ?? &#39;jsp&#39;}/.console_history</code>.</p><h5 id="servername" tabindex="-1">serverName? <a class="header-anchor" href="#servername" aria-label="Permalink to “serverName?”">​</a></h5><blockquote><p><code>optional</code> <strong>serverName?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L44" target="_blank" rel="noreferrer">startConsole.ts:44</a></p><p>Server name for the title bar.</p><h5 id="stdin" tabindex="-1">stdin? <a class="header-anchor" href="#stdin" aria-label="Permalink to “stdin?”">​</a></h5><blockquote><p><code>optional</code> <strong>stdin?</strong>: <code>ReadStream</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L52" target="_blank" rel="noreferrer">startConsole.ts:52</a></p><p>Terminal input; defaults to <code>process.stdin</code>.</p><h5 id="stdout" tabindex="-1">stdout? <a class="header-anchor" href="#stdout" aria-label="Permalink to “stdout?”">​</a></h5><blockquote><p><code>optional</code> <strong>stdout?</strong>: <code>WriteStream</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L50" target="_blank" rel="noreferrer">startConsole.ts:50</a></p><p>Terminal output; defaults to <code>process.stdout</code>. Its color depth picks the theme.</p><h5 id="supervisor" tabindex="-1">supervisor <a class="header-anchor" href="#supervisor" aria-label="Permalink to “supervisor”">​</a></h5><blockquote><p><strong>supervisor</strong>: <code>ConsoleSupervisor</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L40" target="_blank" rel="noreferrer">startConsole.ts:40</a></p><h5 id="version" tabindex="-1">version? <a class="header-anchor" href="#version" aria-label="Permalink to “version?”">​</a></h5><blockquote><p><code>optional</code> <strong>version?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L46" target="_blank" rel="noreferrer">startConsole.ts:46</a></p><p>Server version for the title bar.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="console-version" tabindex="-1">CONSOLE_VERSION <a class="header-anchor" href="#console-version" aria-label="Permalink to “CONSOLE_VERSION”">​</a></h3><blockquote><p><code>const</code> <strong>CONSOLE_VERSION</strong>: <code>string</code> = <code>pkg.version</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/version.ts#L6" target="_blank" rel="noreferrer">version.ts:6</a></p><p>Version of the console package, read from its <code>package.json</code> at build time.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="startconsole" tabindex="-1">startConsole() <a class="header-anchor" href="#startconsole" aria-label="Permalink to “startConsole()”">​</a></h3><blockquote><p><strong>startConsole</strong>(<code>options</code>): <code>Promise</code>&lt;<a href="#consolehandle"><code>ConsoleHandle</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/d8f1b7d8e4bbc2ed45a64c10e5a216fe8f60bc6c/packages/console/src/startConsole.ts#L113" target="_blank" rel="noreferrer">startConsole.ts:113</a></p><p>Starts the TUI console on the current terminal and wires it to the host&#39;s supervisor.</p><p>The renderer never exits on Ctrl+C or signals; the app decides what Ctrl+C means and the host owns signals. Each new server link gets a <code>subscribe</code> for every level, and commands and completions travel over it with request ids that the matching result resolves. A fallback on <code>process</code> <code>exit</code>, <code>uncaughtException</code>, and <code>unhandledRejection</code> writes the terminal reset sequence and leaves raw mode when <code>renderer.destroy()</code> never ran. It does nothing else: the host&#39;s own fatal handler kills the child, closes the console, prints the error once, and exits, so a second print or <code>process.exit</code> here would race it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="#startconsoleoptions"><code>StartConsoleOptions</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="#consolehandle"><code>ConsoleHandle</code></a>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>Error when the renderer cannot start, for example because OpenTUI&#39;s native library is missing. The message names the cause so the host can print it and fall back.</p>',81)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};